CREATE TABLE IF NOT EXISTS economic_production_model_changes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sandbox_id uuid NOT NULL, profile_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending', requested_by text NOT NULL, approved_by text, applied_by text, baseline_score numeric(5,2), proposed_score numeric(5,2), rollback_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, change_reason text, created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, applied_at timestamptz, rolled_back_at timestamptz);
CREATE TABLE IF NOT EXISTS economic_production_model_change_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), change_id uuid NOT NULL, profile_id uuid NOT NULL, event_type text NOT NULL, actor_id text NOT NULL, from_status text, to_status text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_prod_model_changes_profile ON economic_production_model_changes(profile_id,created_at DESC);